problems.reference_solution:
SIZES = ('small', 'medium', 'large')


class ParkingLot:
    def __init__(self, small, medium, large):
        self._free = {'small': small, 'medium': medium, 'large': large}
        self._spots = {}

    def park(self, plate, size):
        if plate in self._spots:
            return None
        for spot in SIZES[SIZES.index(size):]:
            if self._free[spot] > 0:
                self._free[spot] -= 1
                self._spots[plate] = spot
                return spot
        return None

    def leave(self, plate):
        spot = self._spots.pop(plate, None)
        if spot is None:
            return False
        self._free[spot] += 1
        return True

    def free(self, size):
        return self._free[size]

